def transform(g):
    pts=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==5]
    iset={i for i,j in pts}; jset={j for i,j in pts}
    t,b=min(iset),max(iset); l,r=min(jset),max(jset)
    marks=[(i,j,g[i][j]) for i,row in enumerate(g) for j,v in enumerate(row) if v not in (0,5)]
    # rectangle corners
    corners={'TL':(t+1,l+1),'TR':(t+1,r-1),'BL':(b-1,l+1),'BR':(b-1,r-1)}
    def dist(p,c): return abs(p[0]-c[0])+abs(p[1]-c[1])
    # each marker -> nearest corner
    assign={}
    for m in marks:
        c=min(corners,key=lambda k:dist(m,corners[k]))
        assign[c]=m[2]
    g=[row[:] for row in g]
    bh=(b-t-1)//2; bw=(r-l-1)//2
    def corner_of(i,j):
        return ('T' if i<t+1+bh else 'B')+('L' if j<l+1+bw else 'R')
    for i in range(t+1,b):
        for j in range(l+1,r):
            k=corner_of(i,j)
            opp=({'TL':'BR','BR':'TL','TR':'BL','BL':'TR'})[k]
            g[i][j]=assign.get(k, assign.get(opp))
    return g
